    98→        if (action === "ban") {
    99→          await MatrixService.banUserFromRoom(
   100→            roomId,
   101→            selectedMember.userId,
   102→            reason || undefined,
   103→          );
   104→        } else if (action === "unban") {
   105→          await MatrixService.unbanUserFromRoom(
   106→            roomId,
   107→            selectedMember.userId,
   108→            reason || undefined,
   109→          );
   110→        } else {
