   116→        }
   117→
   118→        Toast.show({
   119→          type: "success",
   120→          text1: `User ${action === "ban" ? "banned" : action === "unban" ? "unbanned" : "removed"} successfully`,
   121→        });
   122→        NavigationContainerRef.goBack();
   123→      } catch (error) {
   124→        console.error(`Failed to ${action} user:`, error);
   125→        Toast.show({
   126→          type: "error",
   127→          text1: `Failed to ${action} user`,
   128→        });
   129→      } finally {
   130→        setActiveAction(null);
   131→      }
